<?php
namespace Tests\Feature; use App\Jobs\DeliverTicketNotification; use App\Models\Customer; use App\Models\IntegrationDelivery; use App\Models\Ticket; use App\Services\DashboardSummary; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Queue; use Tests\TestCase;
final class PartSixResilienceTest extends TestCase { use RefreshDatabase;
 public function test_dashboard_cache_is_tenant_keyed_and_invalidation_changes_value():void{[$u,$o]=$this->member();$c=Customer::create(['organization_id'=>$o->id,'name'=>'N','email'=>'n@test']);Ticket::create(['organization_id'=>$o->id,'customer_id'=>$c->id,'subject'=>'Cached ticket']);$this->actingAs($u)->getJson("/api/v1/dashboard?organization_id=$o->id")->assertJsonPath('data.cache','miss')->assertJsonPath('data.active',1);$this->actingAs($u)->getJson("/api/v1/dashboard?organization_id=$o->id")->assertJsonPath('data.cache','hit');app(DashboardSummary::class)->forget($o->id);$this->assertFalse(Cache::has(DashboardSummary::key($o->id)));}
 public function test_same_idempotency_key_creates_and_dispatches_once():void{Queue::fake();[$u,$o]=$this->member();$c=Customer::create(['organization_id'=>$o->id,'name'=>'N','email'=>'n@test']);$body=['organization_id'=>$o->id,'customerId'=>$c->id,'subject'=>'Only one outcome','priority'=>'high'];$first=$this->actingAs($u)->withHeader('Idempotency-Key','duplicate-lab-key')->postJson('/api/v1/tickets',$body)->assertCreated();$this->actingAs($u)->withHeader('Idempotency-Key','duplicate-lab-key')->postJson('/api/v1/tickets',$body)->assertCreated()->assertHeader('Idempotency-Replayed','true')->assertJsonPath('data.id',$first->json('data.id'));$this->assertDatabaseCount('tickets',1);$this->assertDatabaseCount('integration_deliveries',1);Queue::assertPushed(DeliverTicketNotification::class,1);}
 public function test_key_reuse_with_different_payload_conflicts():void{Queue::fake();[$u,$o]=$this->member();$c=Customer::create(['organization_id'=>$o->id,'name'=>'N','email'=>'n@test']);$base=['organization_id'=>$o->id,'customerId'=>$c->id,'subject'=>'First operation','priority'=>'high'];$this->actingAs($u)->withHeader('Idempotency-Key','same-key-value')->postJson('/api/v1/tickets',$base)->assertCreated();$this->actingAs($u)->withHeader('Idempotency-Key','same-key-value')->postJson('/api/v1/tickets',array_merge($base,['subject'=>'Different']))->assertConflict();}
 public function test_job_validates_success_and_records_failure():void{Http::fake([config('services.dependency.url').'/*'=>Http::response(['accepted'=>true,'deliveryId'=>'fake-1'])]);[$u,$o]=$this->member();$c=Customer::create(['organization_id'=>$o->id,'name'=>'N','email'=>'n@test']);$ticket=Ticket::create(['organization_id'=>$o->id,'customer_id'=>$c->id,'subject'=>'Notify']);$delivery=IntegrationDelivery::create(['organization_id'=>$o->id,'ticket_id'=>$ticket->id,'job_id'=>'11111111-1111-4111-8111-111111111111','correlation_id'=>'request-1']);(new DeliverTicketNotification($delivery->id,$delivery->job_id,$delivery->correlation_id))->handle(app(\App\Services\DependencyClient::class));$this->assertDatabaseHas('integration_deliveries',['id'=>$delivery->id,'status'=>'delivered','attempts'=>1]);}
}
